{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "A human record explicitly describes naloxone (the query) as having poor oral bioavailability after oral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "The closest analogue naltrexone has an oral bioavailability of ~5% in healthy male volunteers due to extensive first-pass hepatic metabolism; other naltrexone reports range from 5% to 40%, with most below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Butorphanol, a related morphinan opioid, has an absolute oral bioavailability of 5–17% after oral administration, supporting low oral F for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a close analogue with 6-methylene and N-cyclopropylmethyl modifications, has an absolute oral bioavailability of 41%, showing that some structural changes can raise F above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Naloxegol, a PEGylated naloxone derivative, has a simulated oral bioavailability of 0.90, but this modification is specifically designed to alter metabolism/transport and is not representative of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is naloxone, an N-allyl morphinan opioid antagonist. Direct evidence describes naloxone as having poor oral bioavailability, and the closest analogue naltrexone has predominantly low oral bioavailability (most reports 5–20%, with ~5% in a controlled study). Related morphinans such as butorphanol also show low oral F. High-F analogues (nalmefene, naloxegol) require structural modifications absent in the query. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No quantitative absolute oral bioavailability value for naloxone itself in the supplied evidence; the direct record is qualitative ('poor').",
    "Naltrexone oral bioavailability reports vary widely (5–60%), so the closest analogue evidence is quantitatively heterogeneous.",
    "High-F analogues (nalmefene, naloxegol, samidorphan) differ by structural modifications whose quantitative effect on the query is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

